export const pairings: Pairing[] = rows.map(([a,b,novelty,why,dish,method]) => {
  const ai=ingredients.find(i=>i.id===a)!; const bi=ingredients.find(i=>i.id===b)!;
  const shared=ai.compounds.filter(c=>bi.compounds.some(d=>d.name===c.name));
  return {id:[a,b].sort().join(':'),a,b,novelty,type:shared.length?'bridge':'contrast',connection:shared.length?shared[0].name:`${ai.notes[0]} × ${bi.notes[0].toLowerCase()}`,why,dish,method};
});
export const getIngredient=(id:string)=>ingredients.find(i=>i.id===id)!;
export const otherIngredient=(p:Pairing,id:string)=>getIngredient(p.a===id?p.b:p.a);
export const noveltyLabel=(n:number)=>n===1?'Familiar':n===2?'Unexpected':'Exploratory';
export const isPlantIngredient=(i:Ingredient)=>!['Dairy','Meat','Seafood','Egg'].includes(i.category)&&i.id!=='honey';
export function findPairings(seed:string,type:string,novelty:number,plantOnly=false) {
 return pairings.filter(p=>(p.a===seed||p.b===seed)&&(type==='all'||p.type===type)&&(!plantOnly || (isPlantIngredient(getIngredient(p.a))&&isPlantIngredient(getIngredient(p.b))))).sort((a,b)=>Math.abs(a.novelty-novelty)-Math.abs(b.novelty-novelty)||a.id.localeCompare(b.id));
}

const ingredientAliases: Record<string,string[]> = {
  aubergine:['eggplant'], courgette:['zucchini'], rocket:['arugula'], coriander:['cilantro'],
  beetroot:['beet'], celeriac:['celery root'], prawn:['shrimp'], yoghurt:['yogurt','greek yoghurt','greek yogurt'],
  'red-pepper':['bell pepper','capsicum'], 'soy-sauce':['soya sauce'], 'sichuan-pepper':['szechuan pepper'],
  'green-tea':['sencha'], 'red-lentil':['lentils'], chickpea:['garbanzo'], corn:['corn'],
  'green-bean':['string bean','french bean'], 'brussels-sprout':['brussels sprouts'], egg:['eggs'],
  'sweet-potato':['sweet potatoes'], potato:['potatoes'], 'pine-nut':['pignoli'],
};
export function matchesIngredient(ingredient:Ingredient, query:string) {
  const text=[ingredient.name,ingredient.id.replaceAll('-',' '),ingredient.category,...ingredient.notes,...ingredient.compounds.map(c=>c.name),...(ingredientAliases[ingredient.id]||[])].join(' ').toLocaleLowerCase();
  return query.trim().toLocaleLowerCase().split(/\s+/).every(term=>text.includes(term));
}
